export function getClipTaxon(key: string): BannonClipTaxon | undefined {
  return BANNON_CLIP_TAXONOMY.find(t => t.key === key);
}

export function clipsByFamily(family: ClipFamily): BannonClipTaxon[] {
  return BANNON_CLIP_TAXONOMY.filter(t => t.family === family);
}

export function clipsByCast(cast: ClipCast): BannonClipTaxon[] {
  return BANNON_CLIP_TAXONOMY.filter(t => t.cast === cast);
}

export function clipsBySkeleton(skeleton: SkeletonKind): BannonClipTaxon[] {
  return BANNON_CLIP_TAXONOMY.filter(t => t.skeleton === skeleton);
}
